-- G検定チートシートの用語辞書監査で見つかった「関数系」の薄い箇所を埋める。
-- ミニマックス法(専用問題が無く他問の脇役でしか出ていなかった)、SELU・Mish(活性化関数)、
-- ヒンジ損失・距離指標(機械学習の概要)。既存の出題形式・explanation_data の流儀に合わせる。
BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('g-kentei-q52', '2. 人工知能をめぐる動向',
   '2人が交互に手を選ぶゲームの先読みで、自分の番では自分に最も有利な手（最大）を、相手の番では自分に最も不利な手（最小）を選ぶと仮定して評価する探索の基本はどれか。',
   NULL::text,
   '["ミニマックス法","αβ法（アルファ・ベータ枝刈り）","モンテカルロ木探索","深さ優先探索"]',
   0, '[0]', 'single',
   '{"asked":"自分の番は最大化・相手の番は最小化という前提で先読みする探索手法を選ぶ問題。","point":"『自分は最大、相手は最小を選ぶ前提で交互に評価する』なら、ミニマックス法。","why_asked":"同じ場面で使われるαβ法と役割を混同しやすい。αβ法はミニマックス法の計算を高速化する技法であって、別の評価方針ではない、という主従関係がよく問われる。","kid":"じゃんけんで『相手は自分が一番嫌がる手を出してくる』と決めつけて、それでも一番マシな手を選ぶ考え方。","terms":[["ミニマックス法","自分の番は最大、相手の番は最小の評価値を選ぶと仮定して先読みする探索の基本"],["αβ法（アルファ・ベータ枝刈り）","ミニマックス法と同じ評価方針のまま、結果に影響しない枝を切り捨てて計算を減らす高速化技法"],["モンテカルロ木探索","ランダムなシミュレーションを繰り返して手の良さを統計的に推定する探索手法"]],"eg":"将棋で『相手は絶対に自分が一番困る手を指してくる』と決めてかかり、その中で一番マシな未来を選ぶ考え方。","think":"誰が『最大』を選び、誰が『最小』を選ぶかに注目する。自分の番では自分に一番良い（最大）手を選び、相手の番では相手が自分に一番不利な（＝自分にとって最小の）手を選ぶと仮定して、木を下から評価していく。この交互の最大・最小の仮定そのものがミニマックス法。","vs":"αβ法はこの評価方針を変えずに探索を高速化するだけの技法で、評価方針そのものではない。モンテカルロ木探索は評価をランダムなシミュレーションで代用する別方式、深さ優先探索はどの順で木を掘るかを決めるだけで最大・最小の評価方針を含まない。","usecase":"将棋・チェス・オセロなど、二人が交互に手を指すゲームAIの基本設計に使う。","opt":["正解。自分は最大、相手は最小を選ぶという前提で交互に評価するのがミニマックス法。","同じ前提から不要な探索を切り捨てる高速化技法で、評価の考え方自体はミニマックス法と同じ。ここで問われている『交互に最大・最小を仮定する』考え方そのものではない。","ランダムなシミュレーションを繰り返して手の良さを推定する手法で、最大・最小を交互に仮定する考え方とは別物。","手を掘り下げる順番を決めるだけの探索の進め方で、評価値を最大・最小どちらで見るかという考え方は含まれない。"]}'),

  ('g-kentei-q53', '3. 機械学習の概要',
   'SVM（サポートベクトルマシン）で使われ、正しく分類できていても、境界からの余裕（マージン）が一定に満たないと罰則を与える損失関数はどれか。',
   NULL::text,
   '["ヒンジ損失","交差エントロピー損失","平均二乗誤差（MSE）","平均絶対誤差（MAE）"]',
   0, '[0]', 'single',
   '{"asked":"正しく分類できていてもマージンが足りないと罰則を与える、SVM特有の損失関数を選ぶ問題。","point":"『正解していてもマージン不足なら罰則』と出たら、ヒンジ損失。","why_asked":"分類の損失関数というと交差エントロピーを思い浮かべがちだが、SVMはマージンという独自の考え方に基づくヒンジ損失を使う、という対応関係が問われる。","kid":"テストで正解しても、ギリギリの点数だったら『もっと余裕を持って正解しなさい』と追加の宿題が出るイメージ。","terms":[["ヒンジ損失","正しく分類できていてもマージンが一定に満たないと罰則を与える、SVMで使われる損失関数"],["マージン","分類の境界から、一番近いデータ点までの余裕（距離）"],["サポートベクトル","マージンの境界上、または内側に入り込んでいる、境界の位置を決めるのに直接影響するデータ点"]],"eg":"川に橋をかけるとき、対岸ギリギリではなく余裕を持って着地するよう求める採点基準。","think":"多くの損失関数は『間違えたかどうか』だけを見るが、ヒンジ損失は『正しく分類できていても、境界からの余裕（マージン）が一定値未満なら追加の損失を与える』という点が特徴。これによりSVMは単に分類できるだけでなく、余裕を持って分類できる境界線を選ぶよう学習する。","calc":"点のスコアが0.5、必要なマージンが1の場合\nヒンジ損失 = max(0, 1 − 0.5)\n= max(0, 0.5)\n= 0.5\n\nスコアが1.5（マージン十分）の場合\nヒンジ損失 = max(0, 1 − 1.5)\n= max(0, −0.5)\n= 0","vs":"交差エントロピー損失は確率分布同士のズレを測るもので、マージンという考え方を使わない。MSE・MAEは数値予測（回帰）の損失関数で、分類の境界からの余裕とは無関係。","usecase":"SVMで、単に分類できるだけでなく汎化性能の高い（余裕を持った）境界線を学習させたいときに使う損失関数。","opt":["正解。正しく分類できていても、マージンが一定に満たない場合に罰則を与える、SVMで使われる損失関数。","分類問題でよく使われる損失関数だが、確率分布同士のズレを測るもので、マージンという考え方は使わない。","数値の予測のズレを2乗して測る損失関数で、分類の境界からの余裕という考え方は使わない。","数値の予測のズレを絶対値で測る損失関数で、こちらもマージンという考え方は使わない。"]}'),

  ('g-kentei-q54', '3. 機械学習の概要',
   '2点間の距離を、各軸のずれの絶対値をそのまま足し合わせて求める（碁盤の目状の道のりのような）距離はどれか。',
   NULL::text,
   '["マンハッタン距離","ユークリッド距離","コサイン類似度","標準偏差"]',
   0, '[0]', 'single',
   '{"asked":"各軸のずれの絶対値をそのまま足し合わせる、格子状の道のりのような距離の測り方を選ぶ問題。","point":"『絶対値をそのまま足す、碁盤の目状の道のり』ならマンハッタン距離。『2乗して平方根』ならユークリッド距離。","why_asked":"距離の測り方は複数あり、日常的な直線距離（ユークリッド距離）としか知らないと、格子状の道のり（マンハッタン距離）を問われたときに区別できない。","kid":"碁盤の目のように区切られた街を、斜めに突っ切れずに縦横だけで移動するときの道のりの長さ。","terms":[["マンハッタン距離","各軸のずれの絶対値をそのまま足し合わせる距離。碁盤の目状の道のりに例えられる"],["ユークリッド距離","各軸のずれを2乗して足し、平方根を取る直線距離"],["コサイン類似度","2つのベクトルの向きの近さを測る指標で、距離とは考え方が異なる"]],"eg":"碁盤の目状の街（マンハッタンの街並みが由来）を、斜め移動できずに縦横だけで歩いたときの道のりの長さ。","think":"直線でひとっ飛びできるなら距離は短くなる（ユークリッド距離）。しかし縦横にしか進めない道なら、各方向のずれをそのまま足し合わせた分だけ歩く必要がある（マンハッタン距離）。『2乗して平方根』か『絶対値をそのまま足す』かで見分ける。","calc":"点A(1,2)と点B(4,6)の場合\n横のずれ: 4−1=3\n縦のずれ: 6−2=4\n\nユークリッド距離:\n3の2乗=9、4の2乗=16\n9+16=25\n25の平方根=5\n\nマンハッタン距離:\n3と4をそのまま足す\n3+4=7","vs":"ユークリッド距離は同じ2点でも斜めの直線距離を測るので、マンハッタン距離より短くなる（この例では5と7）。コサイン類似度はそもそも距離ではなく向きの近さを測る指標。","usecase":"k-NNやクラスタリングで、データ同士の近さをどう定義するかによって結果が変わるため、状況に応じて選ぶ。","viz":"<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ2点でも、測り方で距離が変わる</text><line x1=\"40\" y1=\"115\" x2=\"40\" y2=\"30\" stroke=\"#2a2f3f\"/><line x1=\"40\" y1=\"115\" x2=\"300\" y2=\"115\" stroke=\"#2a2f3f\"/><circle cx=\"70\" cy=\"105\" r=\"3.5\" fill=\"#e8eaf0\"/><text x=\"70\" y=\"122\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">A</text><circle cx=\"230\" cy=\"45\" r=\"3.5\" fill=\"#e8eaf0\"/><text x=\"238\" y=\"42\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">B</text><line x1=\"70\" y1=\"105\" x2=\"230\" y2=\"45\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><text x=\"185\" y=\"65\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">ユークリッド距離=5</text><path d=\"M70 105 L230 105 L230 45\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.8\"/><text x=\"150\" y=\"118\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">マンハッタン距離=7（3+4）</text></svg>","opt":["正解。各軸のずれの絶対値をそのまま足し合わせる、碁盤の目状の道のりに例えられる距離。","各軸のずれを2乗して足し、平方根を取る、直線距離としての距離の測り方。","2つのベクトルの向きの近さを測る指標で、距離そのものではない。","データの散らばり具合を表す値で、2点間の距離を測るものではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('g-kentei-j-q46', '5. ディープラーニングの要素技術',
   'ReLU系の活性化関数のうち、自己正規化（self-normalizing）という性質を持ち、深い層を通しても出力の平均・分散が一定に近づくよう設計されたものはどれか。',
   NULL::text,
   '["SELU","Leaky ReLU","GELU","ソフトプラス関数"]',
   0, '[0]', 'single',
   '{"asked":"深い層を通しても平均・分散が一定に近づくよう設計された、自己正規化の性質を持つ活性化関数を選ぶ問題。","point":"『自己正規化』という言葉が出たら、SELU。","why_asked":"ReLU系の活性化関数（Leaky ReLU・ELU・GELU・SELU）は似た見た目・目的で混同しやすい。名前ではなく『何のために工夫されたか』で区別できるかを問う定番。","kid":"毎回自分で姿勢を整え直して、猫背にならないようにしてくれる活性化関数、というイメージ。","terms":[["SELU（Scaled Exponential Linear Unit）","特定の係数で出力をスケーリングし、深い層でも平均・分散が一定に近づくよう自己正規化する活性化関数"],["自己正規化","層を重ねても出力の平均・分散が特定の値に近づいていく性質。バッチ正規化を使わなくても安定しやすい"],["ELU（Exponential Linear Unit）","負の領域を指数関数でなめらかにし、出力の平均を0に近づける活性化関数"]],"eg":"毎回姿勢を自分で直して、猫背やそっくり返りにならないよう調整してくれる椅子のようなもの。","think":"『自己正規化』というキーワードは、正則化やバッチ正規化と混同しやすいが、ここでは活性化関数そのものが持つ性質を指す。SELUは特定の係数（α, λ）を使うことで、層を重ねても出力の平均・分散が一定の値に近づいていくよう設計されている。これによりバッチ正規化を使わなくても学習が安定しやすい。","vs":"Leaky ReLUとELUは負の領域の傾き方に工夫があるが自己正規化の係数設計は無い。GELUはなめらかな形が特徴で、これも自己正規化のための特別な係数は持たない。","usecase":"バッチ正規化を層に挟みにくい構成（例: 全結合層主体のネットワーク）で、学習を安定させたいときに使う。","viz":"<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">負側はなめらかに沈み、正側はReLUよりわずかに急な傾き</text><line x1=\"30\" y1=\"105\" x2=\"310\" y2=\"105\" stroke=\"#2a2f3f\"/><line x1=\"170\" y1=\"24\" x2=\"170\" y2=\"118\" stroke=\"#2a2f3f\"/><path d=\"M30 105 L170 105 L310 45\" fill=\"none\" stroke=\"#555e70\" stroke-width=\"1.6\"/><text x=\"300\" y=\"40\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">ReLU</text><path d=\"M30 98 C 80 108, 130 105, 170 105 C 220 105, 260 75, 310 30\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"290\" y=\"24\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">SELU</text><text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">係数（α,λ）で出力の広がりを一定に近づける＝自己正規化</text></svg>","opt":["正解。SELUは特定の係数（α,λ）により、深い層を通しても出力の平均・分散が一定に近づくよう設計された自己正規化活性化関数。","負の領域にわずかな傾きを残してdying ReLUを防ぐ工夫で、自己正規化の性質は持たない。","ReLUをなめらかにした形の活性化関数で、自己正規化のための特別な係数設計はない。","出力を滑らかに0以上へ押し上げる関数で、自己正規化の性質は持たない。"]}'),

  ('g-kentei-j-q47', '5. ディープラーニングの要素技術',
   'Swishと同じくなめらかな形を持ちながら、tanhとsoftplusを組み合わせた式（x×tanh(softplus(x))）で定義される活性化関数はどれか。',
   NULL::text,
   '["Mish","Swish（SiLU）","GELU","ソフトプラス関数"]',
   0, '[0]', 'single',
   '{"asked":"tanhとsoftplusを組み合わせた式で定義される、なめらかな活性化関数を選ぶ問題。","point":"『tanhとsoftplusの組み合わせ』と出たら、Mish。","why_asked":"Swish・GELU・Mishはどれも『なめらかでReLUより高性能』とされる似た系統の活性化関数で、式の中身の違いで区別できるかが問われる。","kid":"ソフトプラスという緩やかな坂を、さらにtanhでなめらかに整えた形の関数。","terms":[["Mish","x×tanh(softplus(x))で定義される、なめらかな活性化関数"],["Swish（SiLU）","x×シグモイド(x)で定義される、なめらかな活性化関数"],["ソフトプラス関数","log(1+e^x)で定義される、ReLUをなめらかにした関数"]],"eg":"急な坂道（ReLU）をなだらかなスロープに作り替えるような工夫。Mishはそのスロープの作り方がSwishと少し違う流派。","think":"Swish・GELU・Mishはどれも『0付近をなめらかにして、負の値もわずかに通す』という似た狙いを持つが、式の中身が違う。Mishはsoftplus（=log(1+e^x)）という緩やかな坂の値をtanhでさらに−1〜1に整え、それを元のxに掛け合わせる。この『tanhとsoftplusの組み合わせ』という式の構造がMish固有の特徴。","vs":"Swishはtanhでなくシグモイドをxにかけた式。GELUは標準正規分布の累積分布関数を使う別の式。ソフトプラス関数はMishの式の材料の一つであって、それ単体はMishではない。","usecase":"画像認識系の一部のモデルで、ReLUの代わりに使うと精度がわずかに上がる報告がある活性化関数。","opt":["正解。Mishはx×tanh(softplus(x))という式で定義され、Swishと似た滑らかな形を持つ。","x×シグモイド(x)で定義される、Mishとよく似た滑らかな活性化関数だが、式の中身がtanhとsoftplusの組み合わせではない。","標準正規分布の累積分布関数を使って定義される、また別の滑らかな活性化関数。","log(1+e^x)で定義される関数そのもので、Mishの式の一部として使われるが、それ単体では別の関数。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-j'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
